{
  "technical_and_design_decisions": [
    "Use Java 17 and Spring Framework 6 / Spring Boot 3 as the baseline runtime.",
    "For U1, implement Azure Event Hubs source and sink modules using the official Azure Event Hubs SDK for Java (azure-messaging-eventhubs).",
    "For U2, integrate Spring XD with IPython/Jupyter via the Jupyter Kernel Gateway REST API rather than embedding a Python process.",
    "For U3, add a backward-compatible configuration loader that preserves legacy installation directories and servers.yml, allowing copy/reuse during upgrade.",
    "For U4, implement a 'direct' binder in Spring Cloud Stream that connects modules via an in-process channel, eliminating messaging middleware.",
    "For U5, build REST APIs with Spring WebFlux/MVC controllers and a service layer to perform CRUD on stream and batch definitions in xd-admin.",
    "For U6, define a ModuleRegistry abstraction with stub/in-memory implementations to enable mock stream creation via registry APIs.",
    "For U7, relocate spring-cloud-stream-modules into the spring-cloud repository using Gradle multi-project layout and update CI/build files.",
    "For U8, implement an in-memory StreamDefinitionRepository using a ConcurrentHashMap that conforms to the existing repository interface and does not persist."
  ],
  "assumptions": [
    "A single experienced Java/Spring developer performs all work; estimates are for development effort only, not elapsed calendar time.",
    "Existing source code, build systems, and CI pipelines for Spring XD, Spring Cloud Stream, and Spring Cloud Data are available and modifiable.",
    "Automated testing (unit/integration) is included within each feature activity; a separate activity covers cross-cutting integration, build, and docs.",
    "IPython integration is performed through a kernel gateway HTTP interface, not by embedding a Python interpreter inside the JVM.",
    "The term 'servers.yml' refers to Spring XD server configuration files in a known config directory that must be retained on upgrade.",
    "No external messaging middleware is required for the direct-binding feature (U4).",
    "Effort is expressed in work-hours; a standard 8-hour workday is assumed but calendar duration is out of scope."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Analyze the user stories, define architecture, APIs, and detailed design for all features, and set up the WBS and development plan.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Relocate spring-cloud-stream-modules (U7)",
      "activity_description": "Move existing spring-cloud-stream-modules from the s-c-s repository to the s-c repository, update Gradle builds, dependencies, and CI configuration, and verify compilation.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Azure Event Hubs connector modules (U1)",
      "activity_description": "Develop source and sink modules for reading from and writing to Azure Event Hubs using the Azure SDK, including configuration, error handling, and unit tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "IPython Notebook integration (U2)",
      "activity_description": "Implement integration between Spring XD and IPython/Jupyter Notebook via Kernel Gateway REST API to allow interactive real-time data computations, including client code and tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A5",
      "activity_name": "Upgrade config preservation (U3)",
      "activity_description": "Modify Spring XD installer/upgrader and configuration loader to retain older installation directories/files and reuse servers.yml configurations from previous installs.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Direct module binding in Spring Cloud Stream (U4)",
      "activity_description": "Implement a direct binder/binding option that connects modules in-process without messaging middleware, including configuration properties, wiring, and tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "REST API foundation for xd-admin CRUD (U5)",
      "activity_description": "Create REST controllers, DTOs, and service layer to interact with xd-admin and perform CRUD operations on streaming and batch pipeline definitions, with integration tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A8",
      "activity_name": "ModuleRegistry stubs and mock streams (U6)",
      "activity_description": "Define ModuleRegistry interface and provide stub/in-memory implementations so developers can create mock streams by interacting with registry APIs; include tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A9",
      "activity_name": "In-memory stream definition repository (U8)",
      "activity_description": "Implement a non-persistent in-memory StreamDefinitionRepository (e.g., ConcurrentHashMap) for simplified development experience, conforming to the repository interface, with tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-cutting integration, build, and documentation",
      "activity_description": "Set up CI builds, perform end-to-end integration testing of all features, write developer documentation and migration notes, and finalize the increment.",
      "most_likely_effort": 48
    }
  ],
  "reported_total": {
    "most_likely_effort": 400
  }
}

